'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dcartesianSquare = require( './../lib/dcartesiansquare.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dcartesianSquare, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( dcartesianSquare.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function computes the Cartesian square', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( 8 );
	expected = new Float64Array( [ 1.0, 1.0, 1.0, 2.0, 2.0, 1.0, 2.0, 2.0 ] );

	dcartesianSquare( x.length, x, 1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = new Float64Array( 18 );
	expected = new Float64Array([
		1.0,
		1.0,
		1.0,
		2.0,
		1.0,
		3.0,
		2.0,
		1.0,
		2.0,
		2.0,
		2.0,
		3.0,
		3.0,
		1.0,
		3.0,
		2.0,
		3.0,
		3.0
	]);

	dcartesianSquare( x.length, x, 1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	x = new Float64Array( [ 5.0 ] );
	out = new Float64Array( 2 );
	expected = new Float64Array( [ 5.0, 5.0 ] );

	dcartesianSquare( 1, x, 1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function returns a reference to the output array', function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( 8 );
	y = dcartesianSquare( x.length, x, 1, out, 2 );

	t.strictEqual( y, out, 'same reference' );
	t.end();
});

tape( 'if provided an `N` parameter equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( [ 3.0, 4.0, 5.0, 6.0 ] );
	expected = new Float64Array( [ 3.0, 4.0, 5.0, 6.0 ] );

	dcartesianSquare( 0, x, 1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a stride for `x`', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array([
		1.0, // 0
		0.0,
		2.0, // 1
		0.0
	]);
	out = new Float64Array( 8 );
	expected = new Float64Array( [ 1.0, 1.0, 1.0, 2.0, 2.0, 1.0, 2.0, 2.0 ] );

	dcartesianSquare( 2, x, 2, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a negative stride for `x`', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array([
		2.0, // 1
		1.0  // 0
	]);
	out = new Float64Array( 8 );
	expected = new Float64Array( [ 1.0, 1.0, 1.0, 2.0, 2.0, 1.0, 2.0, 2.0 ] );

	dcartesianSquare( 2, x, -1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a leading dimension stride for the output array', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( 16 );
	expected = new Float64Array([
		1.0,
		1.0,
		0.0,
		0.0,
		1.0,
		2.0,
		0.0,
		0.0,
		2.0,
		1.0,
		0.0,
		0.0,
		2.0,
		2.0,
		0.0,
		0.0
	]);

	dcartesianSquare( 2, x, 1, out, 4 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a negative leading dimension stride for the output array', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( 8 );
	expected = new Float64Array( [ 2.0, 2.0, 2.0, 1.0, 1.0, 2.0, 1.0, 1.0 ] );

	dcartesianSquare( 2, x, 1, out, -2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var out;
	var x0;
	var x1;

	x0 = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	out = new Float64Array( 8 );
	expected = new Float64Array( [ 1.0, 1.0, 1.0, 2.0, 2.0, 1.0, 2.0, 2.0 ] );

	dcartesianSquare( 2, x1, 1, out, 2 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});
